const METHOD_OVERRIDES: Record<string, (ctx: Parameters<ApiHandler>[0]) => Promise<Response>> = {
  get_task_details: async (ctx) => {
    if (ctx.req.method === 'POST') return tasks.uploadTaskDetailsFile(ctx);
    if (ctx.req.method === 'DELETE') return tasks.deleteTaskDetailsFile(ctx);
    return tasks.getTaskDetails(ctx);
  },
  manage_portfolio: misc.managePortfolio,
  upload_avatar: misc.uploadAvatar,
};

/** Separa action de query embebida (legacy: action=get_tasks?sort_by=desc). */
export function resolveAction(url: URL, _req: Request): string {
  const raw = url.searchParams.get('action')?.trim();
  if (raw) {
    const cleaned = raw.replace(/\.php$/i, '');
    const qIdx = cleaned.indexOf('?');
    const ampIdx = cleaned.indexOf('&');
    let name = cleaned;
    let inline: string | null = null;
    if (qIdx >= 0) {
      name = cleaned.slice(0, qIdx);
      inline = cleaned.slice(qIdx + 1);
    } else if (ampIdx >= 0) {
      name = cleaned.slice(0, ampIdx);
      inline = cleaned.slice(ampIdx + 1);
    }
    if (inline) {
      const extra = new URLSearchParams(inline);
      extra.forEach((v, k) => {
        if (!url.searchParams.has(k)) url.searchParams.set(k, v);
      });
    }
    return name.trim();
  }
  const path = url.pathname.split('/').filter(Boolean);
  const last = path[path.length - 1];
  if (last && last !== 'arcusx-api') return last.replace(/\.php$/i, '').split('?')[0];
  return '';
}

export async function dispatch(req: Request): Promise<Response> {
  const url = new URL(req.url);
  const action = resolveAction(url, req);
  if (!action) {
    return jsonError(req, 'Parámetro action requerido', 400, 'missing_action');
  }

  const methodOverride = METHOD_OVERRIDES[action];
  const handler = methodOverride ?? ROUTES[action];
  if (!handler) {
    return jsonError(req, `Acción no implementada: ${action}`, 501, 'not_implemented');
  }

  const auth = await authenticateRequest(req);
  const needsJson = req.method !== 'GET' && req.method !== 'HEAD' &&
    !(action === 'upload_avatar' && req.method === 'POST') &&
    !(action === 'get_task_details' && req.method === 'POST');
  const body = needsJson ? await readJsonBody(req) : {};

  const ctx = {
    req,
    url,
    supabase: auth.supabase,
    userId: auth.userId,
    supabaseUserId: auth.supabaseUserId,
    jwt: auth.jwt,
    body,
  };

  try {
    return await handler(ctx);
  } catch (e) {
    if (e instanceof Error) {
      if (e.message === 'Unauthorized') {
        return jsonError(req, 'Unauthorized', 401, 'invalid_or_missing_token');
      }
      if (e.message.includes('admin') || e.message.includes('Forbidden')) {
        return jsonError(req, e.message, 403);
      }
    }
    const msg = e instanceof Error ? e.message : 'Error interno';
    return jsonError(req, msg, 500);
  }
}

import type { SupabaseClient, User } from '@supabase/supabase-js';
import { supabaseService } from './referral-db.ts';
import { bearerToken, verifyArcusxJwt, type ArcusxJwtPayload } from './arcusx-jwt.ts';

export type AuthContext = {
  supabase: SupabaseClient;
  userId: number;
  supabaseUserId?: string;
  jwt?: ArcusxJwtPayload;
};

export async function verifySupabaseAccessToken(
  accessToken: string,
  expectedUserId: string,
  expectedEmail: string,
): Promise<boolean> {
  const url = Deno.env.get('SUPABASE_URL') ?? Deno.env.get('ARCUSX_SUPABASE_URL');
  const anon = Deno.env.get('SUPABASE_ANON_KEY') ??
    Deno.env.get('ARCUSX_SUPABASE_ANON_KEY');
  if (!url || !anon) return false;

  const res = await fetch(`${url}/auth/v1/user`, {
    headers: {
      Authorization: `Bearer ${accessToken}`,
      apikey: anon,
    },
  });
  if (!res.ok) return false;
  const user = await res.json() as { id?: string; email?: string };
  if (user.id !== expectedUserId) return false;
  const email = (user.email ?? '').toLowerCase();
  return email === expectedEmail.toLowerCase();
}

export async function resolveMysqlUserId(
  supabase: SupabaseClient,
  opts: { supabaseUserId?: string; arcusxJwt?: ArcusxJwtPayload },
): Promise<number | null> {
  if (opts.arcusxJwt?.userId) return opts.arcusxJwt.userId;

  if (opts.supabaseUserId) {
    const { data: link } = await supabase
      .from('arcusx_user_link')
      .select('mysql_user_id')
      .eq('supabase_user_id', opts.supabaseUserId)
      .maybeSingle();
    if (link?.mysql_user_id) return link.mysql_user_id as number;

    const { data: user } = await supabase
      .from('arcusx_users')
      .select('id')
      .eq('supabase_user_id', opts.supabaseUserId)
      .maybeSingle();
    if (user?.id) return user.id as number;
  }

  return null;
}

export async function authenticateRequest(req: Request): Promise<{
  supabase: SupabaseClient;
  userId: number | null;
  supabaseUserId?: string;
  jwt?: ArcusxJwtPayload;
}> {
  const supabase = supabaseService();
  const token = bearerToken(req);
  if (!token) {
    return { supabase, userId: null };
  }

  const jwt = await verifyArcusxJwt(token);
  if (jwt) {
    return { supabase, userId: jwt.userId, jwt };
  }

  const { data: { user }, error } = await supabase.auth.getUser(token);
  if (!error && user) {
    const userId = await resolveMysqlUserId(supabase, { supabaseUserId: user.id });
    return { supabase, userId, supabaseUserId: user.id };
  }

  return { supabase, userId: null };
}

export async function requireUser(req: Request): Promise<AuthContext> {
  const auth = await authenticateRequest(req);
  if (auth.userId == null) {
    throw new Error('Unauthorized');
  }
  return {
    supabase: auth.supabase,
    userId: auth.userId,
    supabaseUserId: auth.supabaseUserId,
    jwt: auth.jwt,
  };
}

export async function requireAdmin(req: Request): Promise<AuthContext> {
  const auth = await requireUser(req);
  const { data: row } = await auth.supabase
    .from('arcusx_users')
    .select('is_admin, role')
    .eq('id', auth.userId)
    .single();

  const isAdmin = row?.is_admin === true || row?.role === 'admin' || auth.jwt?.isAdmin;
  if (!isAdmin) throw new Error('Forbidden: admin required');
  return auth;
}

export async function upsertUserLink(
  supabase: SupabaseClient,
  supabaseUserId: string,
  mysqlUserId: number,
): Promise<void> {
  await supabase.from('arcusx_user_link').upsert({
    supabase_user_id: supabaseUserId,
    mysql_user_id: mysqlUserId,
    updated_at: new Date().toISOString(),
  }, { onConflict: 'mysql_user_id' });
}

import { createClient, type SupabaseClient } from '@supabase/supabase-js';

export function supabaseService(): SupabaseClient {
  const url = Deno.env.get('SUPABASE_URL') ??
    Deno.env.get('ARCUSX_SUPABASE_URL');
  const key = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ??
    Deno.env.get('ARCUSX_SUPABASE_SERVICE_ROLE_KEY');
  if (!url || !key) {
    throw new Error(
      'Supabase URL/service key requeridos (SUPABASE_* o ARCUSX_SUPABASE_*)',
    );
  }
  return createClient(url, key, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

export async function refreshPartnerDaily(
  supabase: SupabaseClient,
  partnerId: string,
  statDate: string,
): Promise<void> {
  await supabase.rpc('referral_refresh_daily_totals', {
    p_partner_id: partnerId,
    p_stat_date: statDate,
  });
}

export async function bumpCodeCounters(
  supabase: SupabaseClient,
  codeId: string,
  valid: boolean,
): Promise<void> {
  const { data: row } = await supabase
    .from('referral_codes')
    .select('signup_count, valid_signup_count')
    .eq('id', codeId)
    .single();

  if (!row) return;

  await supabase
    .from('referral_codes')
    .update({
      signup_count: (row.signup_count ?? 0) + 1,
      valid_signup_count: valid
        ? (row.valid_signup_count ?? 0) + 1
        : row.valid_signup_count,
      updated_at: new Date().toISOString(),
    })
    .eq('id', codeId);
}

/**
 * JWT HS256 compatible con backend PHP (Firebase JWT) y admin_login.
 */

function base64UrlEncode(data: Uint8Array | string): string {
  const bytes = typeof data === 'string'
    ? new TextEncoder().encode(data)
    : data;
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function base64UrlDecode(str: string): Uint8Array {
  const pad = '='.repeat((4 - (str.length % 4)) % 4);
  const b64 = (str + pad).replace(/-/g, '+').replace(/_/g, '/');
  const bin = atob(b64);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  return bytes;
}

async function hmacKey(secret: string): Promise<CryptoKey> {
  return crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign', 'verify'],
  );
}

export interface ArcusxJwtPayload {
  userId: number;
  username?: string;
  email?: string;
  isAdmin?: boolean;
  role?: string;
}

export async function signArcusxJwt(
  data: ArcusxJwtPayload,
  expiresInSec: number,
): Promise<string> {
  const secret = Deno.env.get('ARCUSX_JWT_SECRET');
  if (!secret) throw new Error('ARCUSX_JWT_SECRET no configurado');

  const iat = Math.floor(Date.now() / 1000);
  const header = { alg: 'HS256', typ: 'JWT' };
  const payload = {
    iat,
    exp: iat + expiresInSec,
    iss: 'arcusx.pro',
    data: {
      id: data.userId,
      username: data.username,
      email: data.email,
      is_admin: data.isAdmin ?? false,
      role: data.role ?? (data.isAdmin ? 'admin' : 'user'),
    },
  };

  const headerB64 = base64UrlEncode(JSON.stringify(header));
  const payloadB64 = base64UrlEncode(JSON.stringify(payload));
  const signingInput = `${headerB64}.${payloadB64}`;
  const key = await hmacKey(secret);
  const sig = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(signingInput));
  return `${signingInput}.${base64UrlEncode(new Uint8Array(sig))}`;
}

export async function verifyArcusxJwt(token: string): Promise<ArcusxJwtPayload | null> {
  const secret = Deno.env.get('ARCUSX_JWT_SECRET');
  if (!secret) return null;

  const parts = token.split('.');
  if (parts.length !== 3) return null;

  const [headerB64, payloadB64, signatureB64] = parts;
  const signingInput = `${headerB64}.${payloadB64}`;
  const key = await hmacKey(secret);
  const sig = base64UrlDecode(signatureB64);
  const valid = await crypto.subtle.verify(
    'HMAC',
    key,
    sig,
    new TextEncoder().encode(signingInput),
  );
  if (!valid) return null;

  const payload = JSON.parse(new TextDecoder().decode(base64UrlDecode(payloadB64))) as {
    exp?: number;
    data?: {
      id?: number;
      username?: string;
      email?: string;
      is_admin?: boolean;
      role?: string;
    };
  };

  if (payload.exp && payload.exp < Math.floor(Date.now() / 1000) - 300) {
    return null;
  }

  const id = payload.data?.id;
  if (!id) return null;

  return {
    userId: id,
    username: payload.data?.username,
    email: payload.data?.email,
    isAdmin: Boolean(payload.data?.is_admin) || payload.data?.role === 'admin',
    role: payload.data?.role,
  };
}

export function bearerToken(req: Request): string | null {
  const h = req.headers.get('Authorization');
  if (!h?.startsWith('Bearer ')) return null;
  return h.slice(7).trim();
}

import type { SupabaseClient } from '@supabase/supabase-js';
import type { ArcusxJwtPayload } from '../../_shared/arcusx-jwt.ts';

export type ApiContext = {
  req: Request;
  url: URL;
  supabase: SupabaseClient;
  userId: number | null;
  supabaseUserId?: string;
  jwt?: ArcusxJwtPayload;
  body: Record<string, unknown>;
};

export type ApiHandler = (ctx: ApiContext) => Promise<Response>;

export async function readJsonBody(req: Request): Promise<Record<string, unknown>> {
  if (req.method === 'GET' || req.method === 'HEAD') return {};
  try {
    const raw = await req.json();
    return raw && typeof raw === 'object' && !Array.isArray(raw)
      ? raw as Record<string, unknown>
      : {};
  } catch {
    return {};
  }
}

export function qp(url: URL, key: string): string {
  return url.searchParams.get(key)?.trim() ?? '';
}

export function qpInt(url: URL, key: string): number | null {
  const v = url.searchParams.get(key);
  if (v == null || v === '') return null;
  const n = parseInt(v, 10);
  return Number.isNaN(n) ? null : n;
}

export function isValidStellarG(address: string): boolean {
  return /^G[A-Z0-9]{55}$/.test(address);
}

import {
  jsonError,
  jsonResponse,
  jsonSuccess,
} from '../../_shared/arcusx-cors.ts';
import {
  upsertUserLink,
  verifySupabaseAccessToken,
} from '../../_shared/arcusx-auth.ts';
import { signArcusxJwt } from '../../_shared/arcusx-jwt.ts';
import type { ApiContext } from './types.ts';
import { isValidStellarG } from './types.ts';
import { requireUser } from './require.ts';

function normalizeUsername(base: string, supabaseUserId: string): string {
  let b = base.toLowerCase().replace(/[^a-z0-9._-]/g, '').slice(0, 48);
  if (b.length < 2) b = 'user';
  return b;
}

async function uniqueUsername(
  supabase: ApiContext['supabase'],
  base: string,
  supabaseUserId: string,
): Promise<string> {
  const suffix = supabaseUserId.replace(/-/g, '').slice(0, 8);
  const candidates = [base, `${base}_${suffix}`, `${base}_${suffix}_2`, `${base}_${suffix}_3`];
  for (const c of candidates) {
    const { data } = await supabase.from('arcusx_users').select('id').eq('username', c).maybeSingle();
    if (!data) return c;
  }
  return `${base}_${suffix}_${Date.now()}`;
}

export async function syncSupabaseUser(ctx: ApiContext): Promise<Response> {
  const { req, supabase, body } = ctx;
  const supabaseUserId = String(body.supabase_user_id ?? '');
  const email = String(body.email ?? '').toLowerCase();
  const name = String(body.name ?? email.split('@')[0] ?? 'user');
  const accessToken = String(body.supabase_access_token ?? '');

  if (!supabaseUserId || !email) {
    return jsonError(req, 'Datos incompletos', 400);
  }
  if (!accessToken) {
    return jsonError(req, 'Sesión OAuth no válida', 401, 'missing_token');
  }
  const ok = await verifySupabaseAccessToken(accessToken, supabaseUserId, email);
  if (!ok) {
    return jsonError(req, 'Sesión OAuth no válida', 401, 'token_verify_failed');
  }

  const { data: existing } = await supabase
    .from('arcusx_users')
    .select('id, username, email, supabase_user_id')
    .or(`email.eq.${email},supabase_user_id.eq.${supabaseUserId}`)
    .limit(1)
    .maybeSingle();

  let userId: number;
  let username: string;
  let isNewUser = false;

  if (existing) {
    userId = existing.id as number;
    username = existing.username as string;
    if (!existing.supabase_user_id) {
      await supabase.from('arcusx_users').update({
        supabase_user_id: supabaseUserId,
        updated_at: new Date().toISOString(),
      }).eq('id', userId);
    }
  } else {
    isNewUser = true;
    const provided = String(body.username ?? '').trim();
    const base = normalizeUsername(
      provided || name.replace(/\s/g, '') || email.split('@')[0],
      supabaseUserId,
    );
    username = await uniqueUsername(supabase, base, supabaseUserId);
    const { data: inserted, error } = await supabase.from('arcusx_users').insert({
      username,
      email,
      supabase_user_id: supabaseUserId,
      role: 'user',
      is_admin: false,
      password_hash: '',
      created_at: new Date().toISOString(),
      updated_at: new Date().toISOString(),
    }).select('id').single();
    if (error || !inserted) {
      return jsonError(req, error?.message ?? 'Error al crear usuario', 500);
    }
    userId = inserted.id as number;
  }

  await upsertUserLink(supabase, supabaseUserId, userId);

  const token = await signArcusxJwt({ userId, username, email }, 3600 * 24);

  return jsonSuccess(req, {
    token,
    user: { id: userId, username, email },
    is_new_user: isNewUser,
    referral: null,
  });
}

export async function registerWallet(ctx: ApiContext): Promise<Response> {
  const { req } = ctx;
  const auth = await requireUser(ctx);
  const wallet = String(
    ctx.body.private_payout_wallet ?? ctx.body.wallet_address ?? '',
  ).trim();
  if (!isValidStellarG(wallet)) {
    return jsonError(req, 'La dirección de wallet Stellar no es válida.', 400);
  }

  const { data: row } = await auth.supabase
    .from('arcusx_users')
    .select('private_payout_wallet')
    .eq('id', auth.userId)
    .single();

  const previous = String(row?.private_payout_wallet ?? '').trim();
  if (previous === wallet) {
    return jsonSuccess(req, {
      message: 'Sin cambios en la wallet de cobro',
      wallet_address: wallet,
      private_payout_wallet: wallet,
      already_registered: true,
      changed: false,
    });
  }

  const { data: duplicate } = await auth.supabase
    .from('arcusx_users')
    .select('id, username')
    .eq('private_payout_wallet', wallet)
    .neq('id', auth.userId)
    .maybeSingle();

  if (duplicate) {
    return jsonError(req, 'Esa wallet ya está registrada por otro usuario.', 409);
  }

  const { error } = await auth.supabase
    .from('arcusx_users')
    .update({
      private_payout_wallet: wallet,
      wallet_address: wallet,
      updated_at: new Date().toISOString(),
    })
    .eq('id', auth.userId);

  if (error) return jsonError(req, error.message, 500);
  return jsonSuccess(req, {
    message: previous ? 'Wallet de cobro actualizada' : 'Wallet de cobro registrada',
    wallet_address: wallet,
    private_payout_wallet: wallet,
    changed: true,
  });
}

/** Solo wallet registrada en Configuración (ofertas privadas), no Freighter conectada. */
export async function verifyWallet(ctx: ApiContext): Promise<Response> {
  const { req } = ctx;
  const auth = await requireUser(ctx);
  const { data, error } = await auth.supabase
    .from('arcusx_users')
    .select('private_payout_wallet, wallet_address')
    .eq('id', auth.userId)
    .single();

  if (error) {
    return jsonResponse(req, {
      success: true,
      has_wallet: false,
      wallet_address: null,
      private_payout_wallet: null,
    });
  }

  const privateW = String(data?.private_payout_wallet ?? '').trim();
  const legacyW = String(data?.wallet_address ?? '').trim();
  const w = isValidStellarG(privateW)
    ? privateW
    : isValidStellarG(legacyW)
      ? legacyW
      : null;
  return jsonResponse(req, {
    success: true,
    has_wallet: Boolean(w),
    wallet_address: w,
    private_payout_wallet: isValidStellarG(privateW) ? privateW : w,
  });
}

