export function parseSkills(raw: unknown): Array<{ name: string; level: string }> {
  if (!raw) return [];
  if (Array.isArray(raw)) {
    return raw.map((s) => {
      if (typeof s === 'string') return { name: s, level: 'intermediate' };
      const o = s as { name?: string; level?: string };
      return { name: String(o.name ?? ''), level: String(o.level ?? 'intermediate') };
    }).filter((s) => s.name);
  }
  if (typeof raw === 'string') {
    try {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) return parseSkills(parsed);
    } catch {
      /* comma-separated fallback */
    }
    return raw.split(',').map((s) => s.trim()).filter(Boolean)
      .map((name) => ({ name, level: 'intermediate' }));
  }
  return [];
}

export function isPublicProfile(value: unknown): boolean {
  return value !== false && value !== 0 && value !== '0';
}

type TaskRow = {
  user_id?: number | null;
  accepted_applicant_id?: number | null;
  status?: string | null;
  escrow_status?: string | null;
  escrow_id?: string | null;
  price?: number | null;
  escrow_amount?: number | null;
  escrow_platform_fee?: number | null;
};

export function isStrictCompletedTask(t: TaskRow): boolean {
  return t.status === 'completed' && t.escrow_status === 'completed';
}

export function isTransactionTask(t: TaskRow): boolean {
  if (t.status !== 'completed') return false;
  if (t.escrow_status === 'completed') return true;
  if (t.escrow_id && t.escrow_status !== 'refunded') return true;
  return false;
}

export function formatAmount(n: number): string {
  return n.toFixed(7);
}

export function calcNetAmount(
  type: 'paid' | 'received',
  price: number,
  escrowAmount: number | null | undefined,
  platformFee: number,
): number {
  if (type === 'received') return price;
  if (escrowAmount != null && Number(escrowAmount) > 0) return Number(escrowAmount);
  return price / (1 - platformFee);
}

export async function computeUserPublicStats(
  supabase: SupabaseClient,
  userId: number,
): Promise<Record<string, unknown>> {
  const platformFee = await getPlatformFee(supabase);

  const { data: user } = await supabase
    .from('arcusx_users')
    .select('average_rating, total_ratings')
    .eq('id', userId)
    .maybeSingle();

  const [{ count: tasksCreated }, { data: workerTasks }, { data: clientTasks }] = await Promise.all([
    supabase.from('arcusx_tasks').select('*', { count: 'exact', head: true }).eq('user_id', userId),
    supabase.from('arcusx_tasks')
      .select('price, escrow_amount, escrow_platform_fee')
      .eq('accepted_applicant_id', userId)
      .eq('status', 'completed')
      .eq('escrow_status', 'completed'),
    supabase.from('arcusx_tasks')
      .select('price, escrow_amount, escrow_platform_fee')
      .eq('user_id', userId)
      .eq('status', 'completed')
      .eq('escrow_status', 'completed'),
  ]);

  const tasksCompleted = workerTasks?.length ?? 0;

  let totalEarned = 0;
  for (const t of workerTasks ?? []) {
    const price = Number(t.price ?? 0);
    const escrowAmount = t.escrow_amount != null ? Number(t.escrow_amount) : null;
    const fee = Number(t.escrow_platform_fee ?? platformFee);
    if (escrowAmount != null && t.escrow_platform_fee != null) {
      totalEarned += price || escrowAmount * (1 - fee);
    } else {
      totalEarned += price;
    }
  }

  let totalSpent = 0;
  for (const t of clientTasks ?? []) {
    const price = Number(t.price ?? 0);
    const escrowAmount = t.escrow_amount != null ? Number(t.escrow_amount) : null;
    const fee = Number(t.escrow_platform_fee ?? platformFee);
    if (escrowAmount != null) {
      totalSpent += escrowAmount;
    } else if (t.escrow_platform_fee != null) {
      totalSpent += price / (1 - fee);
    } else {
      totalSpent += price / (1 - platformFee);
    }
  }

  const completedAsClient = clientTasks?.length ?? 0;
  const created = tasksCreated ?? 0;
  const completionRate = created > 0
    ? Math.round((completedAsClient / created) * 10000) / 100
    : 0;

  return {
    tasks_completed: tasksCompleted,
    tasks_created: created,
    total_earned: totalEarned,
    total_spent: totalSpent,
    average_rating: Number(user?.average_rating ?? 0),
    total_ratings: Number(user?.total_ratings ?? 0),
    completion_rate: completionRate,
    response_time_avg: null,
  };
}

import { jsonError, jsonResponse } from '../../_shared/arcusx-cors.ts';
import type { ApiContext } from './types.ts';
import { qp, qpInt } from './types.ts';
import { parseSkills } from './stats-helpers.ts';
import { normalizeDisplayText } from '../../_shared/text-encoding.ts';

const STELLAR_G = /^G[A-Z0-9]{55}$/;

type FreelancerRow = {
  id: number;
  username: string;
  avatar_url: string | null;
  bio: string | null;
  skills: unknown;
  average_rating: number;
  total_ratings: number;
  tasks_completed: number;
  total_earned: number;
  public_profile: boolean;
  joined_date: string;
};

function profileScore(row: {
  avatar_url: string | null;
  bio: string | null;
  skills: unknown;
}): number {
  let score = 0;
  if (row.avatar_url?.trim()) score += 1000;
  if (row.bio?.trim()) score += 500;
  const skills = parseSkills(row.skills);
  if (skills.length > 0) score += 200;
  return score;
}

export async function getFreelancers(ctx: ApiContext): Promise<Response> {
  const { req, supabase, url } = ctx;
  const page = Math.max(1, qpInt(url, 'page') ?? 1);
  const limit = Math.min(100, Math.max(1, qpInt(url, 'limit') ?? 20));
  const search = qp(url, 'search');
  const minRating = Number(url.searchParams.get('min_rating') ?? '0') || 0;
  const minTasks = Math.max(0, qpInt(url, 'min_tasks') ?? 0);
  const sortByRaw = qp(url, 'sort_by') || 'rating';
  const sortBy = ['rating', 'tasks_completed', 'joined_date', 'total_earned'].includes(sortByRaw)
    ? sortByRaw
    : 'rating';
  const sortOrder = (url.searchParams.get('sort_order') ?? 'desc').toUpperCase() === 'ASC'
    ? 'asc'
    : 'desc';
  const preferProfile = ['1', 'true'].includes(
    (url.searchParams.get('prefer_profile') ?? '').toLowerCase(),
  );

  let userQuery = supabase
    .from('arcusx_users')
    .select(
      'id, username, avatar_url, bio, skills, average_rating, total_ratings, completed_tasks_count, created_at, public_profile, is_admin, private_payout_wallet',
    )
    .eq('public_profile', true);

  if (search) {
    userQuery = userQuery.ilike('username', `%${search}%`);
  }

  const { data: users, error: usersErr } = await userQuery;
  if (usersErr) return jsonError(req, usersErr.message, 500);

  const eligible = (users ?? []).filter((u) => {
    if (u.public_profile === false || u.public_profile === 0) return false;
    const hasPayout = STELLAR_G.test(String(u.private_payout_wallet ?? '').trim());
    if (u.is_admin) return hasPayout;
    return true;
  });

  const userIds = eligible.map((u) => u.id as number);
  if (userIds.length === 0) {
    return jsonResponse(req, {
      success: true,
      freelancers: [],
      pagination: { total: 0, page, limit, total_pages: 0 },
    });
  }

  const [{ data: ratings }, { data: completedTasks }] = await Promise.all([
    supabase.from('arcusx_ratings').select('rated_id, rating').in('rated_id', userIds),
    supabase
      .from('arcusx_tasks')
      .select('accepted_applicant_id, price')
      .in('accepted_applicant_id', userIds)
      .eq('status', 'completed')
      .eq('escrow_status', 'completed'),
  ]);

  const ratingMap = new Map<number, { sum: number; count: number }>();
  for (const r of ratings ?? []) {
    const id = r.rated_id as number;
    const cur = ratingMap.get(id) ?? { sum: 0, count: 0 };
    cur.sum += Number(r.rating ?? 0);
    cur.count += 1;
    ratingMap.set(id, cur);
  }

  const tasksMap = new Map<number, { count: number; earned: number }>();
  for (const t of completedTasks ?? []) {
    const id = t.accepted_applicant_id as number;
    if (!id) continue;
    const cur = tasksMap.get(id) ?? { count: 0, earned: 0 };
    cur.count += 1;
    cur.earned += Number(t.price ?? 0);
    tasksMap.set(id, cur);
  }

  let rows: FreelancerRow[] = eligible.map((u) => {
    const id = u.id as number;
    const r = ratingMap.get(id);
    const tc = tasksMap.get(id);
    const avgFromRatings = r && r.count > 0 ? r.sum / r.count : 0;
    const averageRating = Number(u.average_rating ?? 0) || avgFromRatings;
    const totalRatings = Number(u.total_ratings ?? 0) || (r?.count ?? 0);
    const tasksCompleted = tc?.count ?? Number(u.completed_tasks_count ?? 0);
    return {
      id,
      username: String(u.username ?? ''),
      avatar_url: (u.avatar_url as string | null) ?? null,
      bio: normalizeDisplayText((u.bio as string | null) ?? '') || null,
      skills: u.skills,
      average_rating: Math.round(averageRating * 100) / 100,
      total_ratings: totalRatings,
      tasks_completed: tasksCompleted,
      total_earned: Math.round((tc?.earned ?? 0) * 100) / 100,
      public_profile: true,
      joined_date: String(u.created_at ?? new Date().toISOString()),
      has_payout_wallet: STELLAR_G.test(String(u.private_payout_wallet ?? '').trim()),
      private_payout_wallet: STELLAR_G.test(String(u.private_payout_wallet ?? '').trim())
        ? String(u.private_payout_wallet).trim()
        : null,
    };
  });

  if (minRating > 0) {
    rows = rows.filter((f) => f.average_rating >= minRating);
  }
  if (minTasks > 0) {
    rows = rows.filter((f) => f.tasks_completed >= minTasks);
  }

  rows.sort((a, b) => {
    if (preferProfile) {
      const ps = profileScore(b) - profileScore(a);
      if (ps !== 0) return ps;
    }
    let cmp = 0;
    switch (sortBy) {
      case 'tasks_completed':
        cmp = a.tasks_completed - b.tasks_completed;
        break;
      case 'joined_date':
        cmp = new Date(a.joined_date).getTime() - new Date(b.joined_date).getTime();
        break;
      case 'total_earned':
        cmp = a.total_earned - b.total_earned;
        break;
      default:
        cmp = a.average_rating - b.average_rating;
        if (cmp === 0) cmp = a.tasks_completed - b.tasks_completed;
    }
    return sortOrder === 'asc' ? cmp : -cmp;
  });

  const total = rows.length;
  const totalPages = total > 0 ? Math.ceil(total / limit) : 0;
  const from = (page - 1) * limit;
  const pageRows = rows.slice(from, from + limit);

  const freelancers = pageRows.map((f) => ({
    ...f,
    skills: parseSkills(f.skills),
  }));

  return jsonResponse(req, {
    success: true,
    freelancers,
    pagination: {
      total,
      page,
      limit,
      total_pages: totalPages,
    },
  });
}

import { jsonError, jsonSuccess } from '../../_shared/arcusx-cors.ts';
import { insertArcusxNotification } from '../../_shared/arcusx-notifications.ts';
import type { ApiContext } from './types.ts';
import { requireUser } from './require.ts';

export async function createEscrow(ctx: ApiContext): Promise<Response> {
  const { req, body } = ctx;
  const auth = await requireUser(ctx);
  const taskId = Number(body.task_id);
  const proposalId = body.proposal_id ? Number(body.proposal_id) : null;
  const contractAddress = body.contract_address ? String(body.contract_address) : null;
  const transactionHash = body.transaction_hash ? String(body.transaction_hash) : null;

  if (!taskId) return jsonError(req, 'task_id es requerido', 400);

  const { data: task } = await auth.supabase
    .from('arcusx_tasks')
    .select('id, user_id, escrow_status, accepted_applicant_id')
    .eq('id', taskId)
    .single();

  if (!task || task.user_id !== auth.userId) {
    return jsonError(req, 'Tarea no encontrada o sin permisos', 404);
  }

  if (contractAddress && transactionHash) {
    const { data: fundedTask } = await auth.supabase
      .from('arcusx_tasks')
      .select('title, accepted_applicant_id')
      .eq('id', taskId)
      .single();
    const { error } = await auth.supabase.from('arcusx_tasks').update({
      escrow_id: contractAddress,
      escrow_status: 'active',
      updated_at: new Date().toISOString(),
    }).eq('id', taskId);
    if (error) return jsonError(req, error.message, 500);
    const workerId = Number(fundedTask?.accepted_applicant_id);
    if (workerId) {
      await insertArcusxNotification(auth.supabase, {
        user_id_mysql: workerId,
        title: 'Escrow fondeado',
        message: `El escrow de "${fundedTask?.title ?? 'tu tarea'}" está activo. Ya puedes comenzar el trabajo.`,
        type: 'success',
      });
    }
    return jsonSuccess(req, { message: 'Firma confirmada' });
  }

  if (!proposalId) return jsonError(req, 'proposal_id es requerido para crear escrow', 400);

  const { data: app } = await auth.supabase
    .from('arcusx_applications')
    .select('applicant_id, worker_wallet_address')
    .eq('id', proposalId)
    .eq('task_id', taskId)
    .single();

  if (!app) return jsonError(req, 'Propuesta no encontrada', 404);

  const { error } = await auth.supabase.from('arcusx_tasks').update({
    accepted_applicant_id: app.applicant_id,
    status: 'in_progress',
    escrow_status: 'pending_signature',
    updated_at: new Date().toISOString(),
  }).eq('id', taskId);

  if (error) return jsonError(req, error.message, 500);
  return jsonSuccess(req, {
    message: 'Escrow preparado',
    worker_wallet: app.worker_wallet_address,
  });
}

export async function selectProposal(ctx: ApiContext): Promise<Response> {
  const { req, body } = ctx;
  const auth = await requireUser(ctx);
  const taskId = Number(body.task_id);
  const proposalId = Number(body.proposal_id);
  const escrowId = body.escrow_id ? String(body.escrow_id) : null;
  const transactionHash = body.transaction_hash ? String(body.transaction_hash) : null;

  const { data: task } = await auth.supabase
    .from('arcusx_tasks')
    .select('id, title, user_id, status')
    .eq('id', taskId)
    .eq('user_id', auth.userId)
    .single();

  if (!task) return jsonError(req, 'Tarea o propuesta no encontrada', 404);

  const { data: app } = await auth.supabase
    .from('arcusx_applications')
    .select('applicant_id, worker_wallet_address')
    .eq('id', proposalId)
    .eq('task_id', taskId)
    .single();

  if (!app) return jsonError(req, 'Propuesta no encontrada', 404);

  const patch: Record<string, unknown> = {
    accepted_applicant_id: app.applicant_id,
    status: 'in_progress',
    updated_at: new Date().toISOString(),
  };
  if (escrowId) {
    patch.escrow_id = escrowId;
    patch.escrow_status = transactionHash ? 'active' : 'pending_signature';
  }

  const { error } = await auth.supabase.from('arcusx_tasks').update(patch).eq('id', taskId);
  if (error) return jsonError(req, error.message, 500);

  await auth.supabase.from('arcusx_applications').update({ status: 'accepted' })
    .eq('id', proposalId);
  await auth.supabase.from('arcusx_applications').update({ status: 'rejected' })
    .eq('task_id', taskId).neq('id', proposalId);

  const workerId = Number(app.applicant_id);
  if (workerId) {
    await insertArcusxNotification(auth.supabase, {
      user_id_mysql: workerId,
      title: 'Propuesta aceptada',
      message:
        `Tu propuesta fue seleccionada para "${task.title ?? 'la tarea'}". ` +
        (escrowId
          ? 'El cliente está configurando el escrow; conecta tu wallet cuando corresponda.'
          : 'El cliente creará el escrow a continuación.'),
      type: 'success',
    });
  }

  return jsonSuccess(req, { message: 'Propuesta seleccionada' });
}

const STELLAR_G = /^G[A-Z0-9]{55}$/;

/** Activa oferta privada tras crear y fondear escrow (sin propuesta previa). */
export async function finalizePrivateOffer(ctx: ApiContext): Promise<Response> {
  const { req, body } = ctx;
  const auth = await requireUser(ctx);
  const taskId = Number(body.task_id);
  const invitedUserId = Number(body.invited_user_id);
  const workerWallet = String(body.worker_wallet_address ?? '').trim();
  const escrowId = String(body.escrow_id ?? '').trim();
  if (!taskId || !invitedUserId || !escrowId) {
    return jsonError(req, 'task_id, invited_user_id y escrow_id son requeridos', 400);
  }
  if (!STELLAR_G.test(workerWallet)) {
    return jsonError(req, 'worker_wallet_address inválida', 400);
  }

  const { data: task, error: taskErr } = await auth.supabase
    .from('arcusx_tasks')
    .select(`
      id, user_id, is_private_invite, invited_user_id, title, price, currency,
      arcusx_users!arcusx_tasks_user_id_fkey (username)
    `)
    .eq('id', taskId)
    .single();

  if (taskErr || !task) return jsonError(req, 'Tarea no encontrada', 404);
  if (task.user_id !== auth.userId) return jsonError(req, 'Sin permisos', 403);
  if (!task.is_private_invite || Number(task.invited_user_id) !== invitedUserId) {
    return jsonError(req, 'La tarea no es una oferta privada válida para este usuario', 400);
  }

  const { data: worker } = await auth.supabase
    .from('arcusx_users')
    .select('id, private_payout_wallet, wallet_address')
    .eq('id', invitedUserId)
    .maybeSingle();

  const profileWallet = String(worker?.private_payout_wallet ?? worker?.wallet_address ?? '').trim();
  if (!STELLAR_G.test(profileWallet) || profileWallet !== workerWallet) {
    return jsonError(req, 'La wallet de cobro del invitado no coincide con su perfil', 400);
  }

  const { data: existingApp } = await auth.supabase
    .from('arcusx_applications')
    .select('id')
    .eq('task_id', taskId)
    .eq('applicant_id', invitedUserId)
    .maybeSingle();

  let applicationId = existingApp?.id as number | undefined;
  if (!applicationId) {
    const { data: inserted, error: insErr } = await auth.supabase
      .from('arcusx_applications')
      .insert({
        task_id: taskId,
        applicant_id: invitedUserId,
        message: `Oferta privada: ${task.title ?? 'tarea'}`,
        worker_wallet_address: workerWallet,
        status: 'accepted',
        created_at: new Date().toISOString(),
      })
      .select('id')
      .single();
    if (insErr) return jsonError(req, insErr.message, 500);
    applicationId = inserted?.id as number;
  } else {
    await auth.supabase
      .from('arcusx_applications')
      .update({
        status: 'accepted',
        worker_wallet_address: workerWallet,
      })
      .eq('id', applicationId);
    await auth.supabase
      .from('arcusx_applications')
      .update({ status: 'rejected' })
      .eq('task_id', taskId)
      .neq('id', applicationId);
  }

  const patch: Record<string, unknown> = {
    accepted_applicant_id: invitedUserId,
    status: 'in_progress',
    escrow_id: escrowId,
    escrow_status: 'active',
    updated_at: new Date().toISOString(),
  };
  if (body.escrow_amount != null) patch.escrow_amount = Number(body.escrow_amount);
  if (body.platform_fee != null) patch.escrow_platform_fee = Number(body.platform_fee);

  const { error: updErr } = await auth.supabase.from('arcusx_tasks').update(patch).eq('id', taskId);
  if (updErr) return jsonError(req, updErr.message, 500);

  const creator = task.arcusx_users as { username?: string } | null;
  const creatorName = creator?.username ?? 'Un cliente';
  const amount = body.escrow_amount != null ? String(body.escrow_amount) : String(task.price ?? '');
  const cur = String((task as { currency?: string }).currency ?? 'USDC');
  await insertArcusxNotification(auth.supabase, {
    user_id_mysql: invitedUserId,
    title: 'Nueva oferta privada',
    message:
      `${creatorName} te envió una oferta privada fondeada: "${task.title ?? 'Tarea'}". ` +
      `Monto: ${amount} ${cur}. Revisa la pestaña Ofertas en tu panel.`,
    type: 'success',
  });

  return jsonSuccess(req, {
    message: 'Oferta privada activada',
    application_id: applicationId,
    escrow_id: escrowId,
  });
}

export async function completeTask(ctx: ApiContext): Promise<Response> {
  const { req, body } = ctx;
  const auth = await requireUser(ctx);
  const taskId = Number(body.task_id);
  const action = String(body.action ?? 'accept');

  const { data: task } = await auth.supabase
    .from('arcusx_tasks')
    .select('*')
    .eq('id', taskId)
    .single();

  if (!task) return jsonError(req, 'Tarea no encontrada.', 404);

  const isClient = task.user_id === auth.userId;
  const isWorker = task.accepted_applicant_id === auth.userId;
  if (!isClient && !isWorker) return jsonError(req, 'No autorizado', 403);

  const patch: Record<string, unknown> = { updated_at: new Date().toISOString() };
  const escrowCompleted = Boolean(body.escrow_completed);
  const taskTitle = String(task.title ?? 'la tarea');

  if (isWorker) {
    if (action !== 'accept') {
      return jsonError(req, 'El trabajador solo puede notificar la entrega', 400);
    }
    patch.worker_accepted_completion = true;
  }

  if (isClient) {
    if (action === 'reject') {
      patch.status = 'rejected';
      if (task.escrow_status) patch.escrow_status = 'refunded';
    } else if (action === 'accept') {
      patch.client_accepted_completion = true;
      if (escrowCompleted) {
        patch.status = 'completed';
        patch.completed_at = new Date().toISOString();
        patch.escrow_status = 'completed';
        patch.escrow_completed_at = new Date().toISOString();
      }
    }
  }

  const { error } = await auth.supabase.from('arcusx_tasks').update(patch).eq('id', taskId);
  if (error) return jsonError(req, error.message, 500);

  if (isWorker && action === 'accept') {
    await insertArcusxNotification(auth.supabase, {
      user_id_mysql: Number(task.user_id),
      title: 'Entrega notificada',
      message:
        `El freelancer avisó que terminó "${taskTitle}". Revisa la entrega y libera el pago cuando quieras.`,
      type: 'info',
    });
    return jsonSuccess(req, {
      message: 'Aviso enviado al cliente. Él decide cuándo liberar el pago.',
      task_id: taskId,
      worker_accepted_completion: 1,
    });
  }

  if (isClient && action === 'accept' && escrowCompleted) {
    const workerId = Number(task.accepted_applicant_id);
    if (workerId > 0) {
      await insertArcusxNotification(auth.supabase, {
        user_id_mysql: workerId,
        title: 'Pago liberado',
        message: `El cliente liberó el pago de "${taskTitle}". Revisa tu wallet.`,
        type: 'success',
      });
    }
    return jsonSuccess(req, {
      message: 'Tarea completada y fondos liberados',
      task_id: taskId,
      status: 'completed',
    });
  }

  return jsonSuccess(req, {
    message: isClient ? 'Confirmación del cliente registrada' : 'Estado actualizado',
    task_id: taskId,
  });
}

import { jsonError, jsonResponse, jsonSuccess } from '../../_shared/arcusx-cors.ts';
import { insertArcusxNotification } from '../../_shared/arcusx-notifications.ts';
import type { ApiContext } from './types.ts';
import { qpInt } from './types.ts';
import { requireUser, requireAdmin } from './require.ts';

export async function createDispute(ctx: ApiContext): Promise<Response> {
  const { req, body } = ctx;
  const auth = await requireUser(ctx);
  const taskId = Number(body.task_id);
  const reason = String(body.reason ?? '').trim();
  const txHash = body.tx_hash ? String(body.tx_hash) : null;

  if (!taskId || !reason) return jsonError(req, 'Datos incompletos', 400);

  const { data: task } = await auth.supabase
    .from('arcusx_tasks')
    .select('id, title, user_id, accepted_applicant_id')
    .eq('id', taskId)
    .single();

  if (!task) return jsonError(req, 'Tarea no encontrada', 404);
  const allowed = task.user_id === auth.userId || task.accepted_applicant_id === auth.userId;
  if (!allowed) return jsonError(req, 'No autorizado', 403);

  const { data, error } = await auth.supabase.from('arcusx_disputes').insert({
    task_id: taskId,
    created_by: auth.userId,
    reason,
    tx_hash: txHash,
    status: 'pending',
    created_at: new Date().toISOString(),
  }).select('id').single();

  if (error) return jsonError(req, error.message, 500);
  await auth.supabase.from('arcusx_tasks').update({ status: 'disputed' }).eq('id', taskId);

  const otherId =
    auth.userId === task.user_id
      ? Number(task.accepted_applicant_id)
      : Number(task.user_id);
  if (otherId > 0) {
    await insertArcusxNotification(auth.supabase, {
      user_id_mysql: otherId,
      title: 'Disputa abierta',
      message: `Se abrió una disputa en "${task.title ?? 'la tarea'}". Revisa los detalles en tu panel.`,
      type: 'warning',
    });
  }

  return jsonSuccess(req, { dispute_id: data?.id });
}

export async function getUserDisputes(ctx: ApiContext): Promise<Response> {
  const { req } = ctx;
  const auth = await requireUser(ctx);

  const { data: rows, error } = await auth.supabase
    .from('arcusx_disputes')
    .select(`
      id, status, resolution, resolved_at,
      arcusx_tasks!inner (
        id, title, price, escrow_id, escrow_status, user_id, accepted_applicant_id
      )
    `)
    .eq('status', 'resolved')
    .order('resolved_at', { ascending: false });

  if (error) return jsonError(req, error.message, 500);

  const disputes: Array<Record<string, unknown>> = [];

  for (const row of rows ?? []) {
    const task = row.arcusx_tasks as {
      id: number;
      title: string;
      price: number;
      escrow_id: string | null;
      escrow_status: string | null;
      user_id: number;
      accepted_applicant_id: number | null;
    } | null;
    if (!task || task.escrow_status !== 'pending_dispute_resolution') continue;
    if (task.user_id !== auth.userId && task.accepted_applicant_id !== auth.userId) continue;

    let resolution: Record<string, unknown> | null = null;
    if (row.resolution) {
      try {
        resolution = typeof row.resolution === 'string'
          ? JSON.parse(row.resolution)
          : row.resolution as Record<string, unknown>;
      } catch {
        resolution = null;
      }
    }

    const decision = resolution?.decision as string | undefined;
    let userRole: 'client' | 'worker' | null = null;
    let needsSignature = false;
    let refundAmount = 0;
    let paymentAmount = 0;

    if (task.user_id === auth.userId) {
      userRole = 'client';
      if (decision === 'client' || decision === 'split') {
        needsSignature = true;
        refundAmount = Number(resolution?.refund_to_client ?? 0);
      }
    } else if (task.accepted_applicant_id === auth.userId) {
      userRole = 'worker';
      if (decision === 'worker' || decision === 'split') {
        needsSignature = true;
        paymentAmount = Number(resolution?.pay_to_worker ?? 0);
      }
    }

    if (!needsSignature || !userRole) continue;

    disputes.push({
      dispute_id: row.id,
      task_id: task.id,
      task_title: task.title,
      price: Number(task.price ?? 0),
      escrow_id: task.escrow_id,
      user_role: userRole,
      decision,
      refund_amount: refundAmount,
      payment_amount: paymentAmount,
      resolved_at: row.resolved_at,
      resolution_reason: resolution?.reason ?? null,
    });
  }

  return jsonResponse(req, { success: true, disputes, count: disputes.length });
}

